```javascript
import * as THREE from 'three/webgpu';
import gsap from 'gsap';
import { TextMesh } from '@/text';

export default function createNode(config, ctx) {
  // Destructure config
  const {
    scenePosition = { x: -1.25, y: -1.1, z: 0, rx: 0, ry: 0, rz: 0, sx: 1, sy: 1, sz: 1 },
    interactions = [],
    cinematicPrimitives = [],
  } = config;

  // Create root group
  const group = new THREE.Group();
  group.position.set(scenePosition.x, scenePosition.y, scenePosition.z);
  group.rotation.set(scenePosition.rx, scenePosition.ry, scenePosition.rz);
  group.scale.set(scenePosition.sx, scenePosition.sy, scenePosition.sz);

  // Load mesh (cached via ctx.glbLoader)
  const glb = ctx.glbLoader.load('/prism-mock/orrery/meshes/gear-a.glb');
  const mesh = glb.scene ? glb.scene.clone() : glb.clone(); // assume .scene if GLTF
  group.add(mesh);

  // Store timeline for cleanup
  let settleTimeline = null;
  let hoverTimeline = null;

  // Weighted-settle entrance (scale overshoot)
  settleTimeline = gsap.timeline({ paused: true });
  settleTimeline.to(group.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: 'power4.out',
    overwrite: 'auto',
  });
  // Set initial overshoot scale
  group.scale.set(1.04, 1.04, 1.04);
  settleTimeline.play();

  // Attach interaction handlers
  const handlers = {};

  // Hover: rise-in (subtle, 0.15 units)
  const hoverInTween = gsap.to(group.position, {
    y: group.position.y + 0.15,
    duration: 0.7,
    ease: 'power3.out',
    paused: true,
    overwrite: 'auto',
  });
  const hoverOutTween = gsap.to(group.position, {
    y: group.position.y,
    duration: 0.7,
    ease: 'power3.out',
    paused: true,
    overwrite: 'auto',
  });

  handlers.hover = (event) => {
    if (event.type === 'pointerenter') {
      hoverInTween.play();
    } else if (event.type === 'pointerleave') {
      hoverOutTween.play();
    }
  };

  // Click: emit hub-features.select
  handlers.click = () => {
    if (ctx.emit) {
      ctx.emit('hub-features.select', {});
    }
  };

  group.userData.handlers = handlers;

  // Apply cinematic primitives
  cinematicPrimitives.forEach((prim) => {
    if (prim.name === 'parallax-scroll') {
      ctx.primitives.parallaxScroll(group, prim.params);
    } else if (prim.name === 'magnetic-cursor') {
      ctx.primitives.magneticCursor(group, prim.params);
    }
  });

  // Cleanup
  group.userData.cleanup = () => {
    // Kill GSAP timelines
    if (settleTimeline) settleTimeline.kill();
    if (hoverInTween) hoverInTween.kill();
    if (hoverOutTween) hoverOutTween.kill();

    // Dispose mesh resources
    mesh.traverse((child) => {
      if (child.isMesh) {
        child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach(m => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      }
    });

    // Remove from parent if any
    if (group.parent) {
      group.parent.remove(group);
    }
  };

  return group;
}
